CREATE TABLE roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE role_permissions (role_id INT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role_id INT UNSIGNED NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id), CHECK(status IN ('active','inactive')));
CREATE TABLE auth_sessions (id CHAR(36) PRIMARY KEY, user_id INT UNSIGNED NOT NULL, access_hash CHAR(64) NOT NULL UNIQUE, refresh_hash CHAR(64) NOT NULL UNIQUE, csrf_hash CHAR(64) NOT NULL, access_expires_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(user_id,expires_at));
CREATE TABLE used_refresh_tokens (token_hash CHAR(64) PRIMARY KEY, session_id CHAR(36) NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(session_id) REFERENCES auth_sessions(id));
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, identity_hash CHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(identity_hash,created_at));
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(1000) NOT NULL DEFAULT '', status VARCHAR(16) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CHECK(status IN ('active','inactive')));
CREATE TABLE customers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, identification VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, phone VARCHAR(40) NOT NULL DEFAULT '', email VARCHAR(190) NOT NULL DEFAULT '', address VARCHAR(300) NOT NULL DEFAULT '', status VARCHAR(16) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CHECK(status IN ('active','inactive')));
CREATE TABLE suppliers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, identification VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, phone VARCHAR(40) NOT NULL DEFAULT '', email VARCHAR(190) NOT NULL DEFAULT '', address VARCHAR(300) NOT NULL DEFAULT '', status VARCHAR(16) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CHECK(status IN ('active','inactive')));
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(140) NOT NULL, description VARCHAR(1000) NOT NULL DEFAULT '', category_id INT UNSIGNED NOT NULL, supplier_id INT UNSIGNED NULL, purchase_price DECIMAL(18,2) NOT NULL, sale_price DECIMAL(18,2) NOT NULL, min_stock INT UNSIGNED NOT NULL DEFAULT 5, status VARCHAR(16) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id), CHECK(purchase_price>=0), CHECK(sale_price>=0), CHECK(status IN ('active','inactive')), INDEX(category_id,status), INDEX(name));
CREATE TABLE inventories (product_id INT UNSIGNED PRIMARY KEY, stock INT NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id), CHECK(stock>=0));
CREATE TABLE sales (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'draft', total DECIMAL(18,2) NOT NULL, request_key CHAR(36) NOT NULL UNIQUE, request_hash CHAR(64) NOT NULL, cancel_reason VARCHAR(500) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(user_id) REFERENCES users(id), CHECK(total>=0), CHECK(status IN ('draft','confirmed','cancelled')), INDEX(status,created_at), INDEX(customer_id,created_at));
CREATE TABLE purchases (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, supplier_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'draft', total DECIMAL(18,2) NOT NULL, request_key CHAR(36) NOT NULL UNIQUE, request_hash CHAR(64) NOT NULL, cancel_reason VARCHAR(500) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(supplier_id) REFERENCES suppliers(id), FOREIGN KEY(user_id) REFERENCES users(id), CHECK(total>=0), CHECK(status IN ('draft','received','cancelled')), INDEX(status,created_at), INDEX(supplier_id,created_at));
CREATE TABLE sale_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sale_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, product_name VARCHAR(140) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(18,2) NOT NULL, subtotal DECIMAL(18,2) NOT NULL, FOREIGN KEY(sale_id) REFERENCES sales(id), FOREIGN KEY(product_id) REFERENCES products(id), UNIQUE(sale_id,product_id), CHECK(quantity>0), CHECK(unit_price>=0), CHECK(subtotal>=0));
CREATE TABLE purchase_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, purchase_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, product_name VARCHAR(140) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(18,2) NOT NULL, subtotal DECIMAL(18,2) NOT NULL, FOREIGN KEY(purchase_id) REFERENCES purchases(id), FOREIGN KEY(product_id) REFERENCES products(id), UNIQUE(purchase_id,product_id), CHECK(quantity>0), CHECK(unit_price>=0), CHECK(subtotal>=0));
CREATE TABLE inventory_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, kind VARCHAR(30) NOT NULL, quantity INT NOT NULL, balance INT NOT NULL, source_type VARCHAR(30) NOT NULL, source_id INT UNSIGNED NULL, reason VARCHAR(500) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(user_id) REFERENCES users(id), CHECK(balance>=0), CHECK(quantity<>0), UNIQUE(product_id,source_type,source_id,kind), INDEX(product_id,created_at));
CREATE TABLE documents (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, entity_type VARCHAR(30) NOT NULL, entity_id INT UNSIGNED NOT NULL, original_name VARCHAR(200) NOT NULL, storage_key VARCHAR(100) NOT NULL UNIQUE, mime_type VARCHAR(80) NOT NULL, size_bytes INT UNSIGNED NOT NULL, provider VARCHAR(10) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(entity_type,entity_id));
CREATE TABLE product_images (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id INT UNSIGNED NOT NULL, document_id INT UNSIGNED NOT NULL UNIQUE, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, message VARCHAR(500) NOT NULL, event_key VARCHAR(120) NOT NULL UNIQUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notification_reads (notification_id BIGINT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, read_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(notification_id,user_id), FOREIGN KEY(notification_id) REFERENCES notifications(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(80) NOT NULL, entity VARCHAR(40) NOT NULL, entity_id VARCHAR(50) NULL, changes JSON NULL, result VARCHAR(16) NOT NULL DEFAULT 'success', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(entity,entity_id), INDEX(created_at));
